// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title VestingVaultMulti
 * @author Based on a request
 * @notice A multi-beneficiary ERC20 token vesting contract with cliffs, linear schedules, and revocation.
 * @dev This contract allows a single owner to create multiple vesting schedules for an ERC20 token.
 * Each schedule defines a beneficiary, a total amount of tokens, a start time, a cliff, a duration,
 * and whether it's revocable. Beneficiaries can claim their vested tokens at any time. The owner
 * can revoke certain schedules, returning the unvested portion of the tokens to the owner and locking
 * the vested amount for the beneficiary. The contract is pausable by the owner.
 * This contract targets OpenZeppelin v4.9.x APIs.
 */
contract VestingVaultMulti is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice The ERC20 token being vested.
    IERC20 public immutable token;

    /// @dev A mapping from a unique schedule ID to its details.
    mapping(uint256 => VestingSchedule) private _schedules;

    /// @dev Counter for creating unique schedule IDs. Starts at 1.
    uint256 private _nextScheduleId;

    /**
     * @notice Defines the structure of a vesting schedule.
     * @param beneficiary The address receiving the vested tokens.
     * @param totalAmount The total amount of tokens to be vested. This value is reduced upon revocation.
     * @param startTime The Unix timestamp when vesting begins.
     * @param cliffDuration The duration in seconds from startTime before any tokens are vested.
     * @param duration The total duration in seconds of the vesting period from startTime.
     * @param amountClaimed The amount of tokens already claimed by the beneficiary.
     * @param revocable A boolean indicating if the schedule can be revoked by the owner.
     * @param isRevoked A boolean indicating if the schedule has been revoked.
     * @param metadataURI A URI pointing to metadata about the vesting schedule.
     */
    struct VestingSchedule {
        address beneficiary;
        uint256 totalAmount;
        uint64 startTime;
        uint64 cliffDuration;
        uint64 duration;
        uint256 amountClaimed;
        bool revocable;
        bool isRevoked;
        string metadataURI;
    }

    /// @notice Emitted when a new vesting schedule is created.
    event ScheduleCreated(
        uint256 indexed scheduleId,
        address indexed beneficiary,
        uint256 totalAmount,
        uint64 startTime,
        uint64 cliffDuration,
        uint64 duration,
        bool revocable,
        string metadataURI
    );

    /// @notice Emitted when a beneficiary claims vested tokens.
    event Claimed(uint256 indexed scheduleId, address indexed beneficiary, uint256 amount);

    /// @notice Emitted when a vesting schedule is revoked by the owner.
    event Revoked(uint256 indexed scheduleId, uint256 unvestedAmountReturned);

    /**
     * @notice Sets up the vesting vault with the specified ERC20 token.
     * @param tokenAddress The address of the ERC20 token to be used for vesting.
     */
    constructor(address tokenAddress) {
        require(tokenAddress != address(0), "VestingVaultMulti: Token cannot be zero address");
        token = IERC20(tokenAddress);
        _nextScheduleId = 1; // Start schedule IDs from 1.
    }

    /**
     * @notice Pauses the contract, preventing schedule creation, claims, and revocations.
     * @dev Can only be called by the owner.
     */
    function pause() public onlyOwner {
        _pause();
    }

    /**
     * @notice Unpauses the contract, re-enabling normal operations.
     * @dev Can only be called by the owner.
     */
    function unpause() public onlyOwner {
        _unpause();
    }

    /**
     * @notice Creates a new vesting schedule.
     * @dev The owner must have approved the contract to spend `totalAmount` of the token.
     * The tokens are transferred into the vault upon creation.
     * @param beneficiary The address that will receive the vested tokens.
     * @param totalAmount The total amount of tokens for this schedule.
     * @param startTime The Unix timestamp for the start of the vesting period.
     * @param cliffDuration The duration in seconds from the start time before any tokens are vested.
     * @param duration The total duration of the vesting period in seconds from the start time.
     * @param revocable Whether the schedule can be revoked by the owner.
     * @param metadataURI A URI for schedule metadata.
     */
    function createSchedule(
        address beneficiary,
        uint256 totalAmount,
        uint64 startTime,
        uint64 cliffDuration,
        uint64 duration,
        bool revocable,
        string calldata metadataURI
    ) public onlyOwner whenNotPaused {
        require(beneficiary != address(0), "VestingVaultMulti: Beneficiary cannot be zero address");
        require(totalAmount > 0, "VestingVaultMulti: Total amount must be greater than zero");
        require(duration > 0, "VestingVaultMulti: Duration must be greater than zero");
        require(cliffDuration <= duration, "VestingVaultMulti: Cliff must be less than or equal to duration");

        uint256 scheduleId = _nextScheduleId;
        _nextScheduleId++;

        _schedules[scheduleId] = VestingSchedule({
            beneficiary: beneficiary,
            totalAmount: totalAmount,
            startTime: startTime,
            cliffDuration: cliffDuration,
            duration: duration,
            amountClaimed: 0,
            revocable: revocable,
            isRevoked: false,
            metadataURI: metadataURI
        });

        token.safeTransferFrom(msg.sender, address(this), totalAmount);

        emit ScheduleCreated(
            scheduleId,
            beneficiary,
            totalAmount,
            startTime,
            cliffDuration,
            duration,
            revocable,
            metadataURI
        );
    }

    /**
     * @notice Revokes a vesting schedule.
     * @dev Can only be called by the owner for revocable, non-revoked schedules.
     * Unvested tokens are transferred back to the owner. The schedule is then updated to
     * permanently lock the vested amount at the time of revocation by adjusting its totalAmount and duration.
     * @param scheduleId The ID of the schedule to revoke.
     */
    function revoke(uint256 scheduleId) public onlyOwner whenNotPaused nonReentrant {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(schedule.beneficiary != address(0), "VestingVaultMulti: Schedule not found");
        require(schedule.revocable, "VestingVaultMulti: Schedule not revocable");
        require(!schedule.isRevoked, "VestingVaultMulti: Schedule already revoked");

        uint256 vested = _getVestedAmountAt(scheduleId, block.timestamp);
        uint256 unvested = schedule.totalAmount - vested;

        schedule.totalAmount = vested;

        // Freeze vesting at the current point by setting the duration to the elapsed time.
        if (block.timestamp > schedule.startTime) {
            schedule.duration = uint64(block.timestamp - schedule.startTime);
        } else {
            // Revoked before start time, so effective duration is 0.
            schedule.duration = 0;
        }

        // The cliff must be <= new duration to maintain the invariant.
        if (schedule.cliffDuration > schedule.duration) {
            schedule.cliffDuration = schedule.duration;
        }

        schedule.isRevoked = true;
        schedule.revocable = false; // A revoked schedule cannot be re-revoked.

        if (unvested > 0) {
            token.safeTransfer(owner(), unvested);
        }

        emit Revoked(scheduleId, unvested);
    }

    /**
     * @notice Allows a beneficiary to claim their vested tokens.
     * @dev The caller must be the beneficiary of the schedule.
     * @param scheduleId The ID of the schedule to claim from.
     */
    function claim(uint256 scheduleId) public whenNotPaused nonReentrant {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(schedule.beneficiary != address(0), "VestingVaultMulti: Schedule not found");
        require(msg.sender == schedule.beneficiary, "VestingVaultMulti: Only beneficiary can claim");

        uint256 releasable = releasableAmount(scheduleId);
        require(releasable > 0, "VestingVaultMulti: No tokens to claim");

        schedule.amountClaimed += releasable;

        token.safeTransfer(schedule.beneficiary, releasable);

        emit Claimed(scheduleId, schedule.beneficiary, releasable);
    }

    /**
     * @notice Gets the details of a specific vesting schedule.
     * @param scheduleId The ID of the schedule.
     * @return The VestingSchedule struct.
     */
    function getSchedule(uint256 scheduleId) public view returns (VestingSchedule memory) {
        return _schedules[scheduleId];
    }

    /**
     * @notice Calculates the total amount of vested tokens for a schedule at the current time.
     * @param scheduleId The ID of the schedule.
     * @return The amount of tokens that have vested.
     */
    function vestedAmount(uint256 scheduleId) public view returns (uint256) {
        require(_schedules[scheduleId].beneficiary != address(0), "VestingVaultMulti: Schedule not found");
        return _getVestedAmountAt(scheduleId, block.timestamp);
    }

    /**
     * @notice Calculates the amount of vested tokens that are available to be claimed.
     * @param scheduleId The ID of the schedule.
     * @return The amount of tokens that can be claimed now.
     */
    function releasableAmount(uint256 scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = _schedules[scheduleId];
        require(schedule.beneficiary != address(0), "VestingVaultMulti: Schedule not found");
        uint256 vested = _getVestedAmountAt(scheduleId, block.timestamp);
        return vested - schedule.amountClaimed;
    }

    /**
     * @dev Internal function to calculate the vested amount for a schedule at a specific timestamp.
     * The calculation is piecewise: 0 until the cliff, then linear vesting until the duration ends.
     * @param scheduleId The ID of the schedule.
     * @param timestamp The Unix timestamp to calculate vested amount at.
     * @return The calculated vested amount.
     */
    function _getVestedAmountAt(uint256 scheduleId, uint256 timestamp) private view returns (uint256) {
        VestingSchedule storage schedule = _schedules[scheduleId];

        uint256 startTime = schedule.startTime;
        uint256 cliffTime = startTime + schedule.cliffDuration;
        uint256 endTime = startTime + schedule.duration;

        if (timestamp < cliffTime) {
            return 0;
        }
        if (timestamp >= endTime) {
            return schedule.totalAmount;
        }

        // Linear vesting period starts after the cliff
        uint256 vestingPeriod = endTime - cliffTime;
        if (vestingPeriod == 0) {
            // This happens if cliffDuration == duration. All vests at endTime.
            // Since timestamp < endTime, nothing has vested yet.
            return 0;
        }

        uint256 timeElapsedInVestingPeriod = timestamp - cliffTime;
        return (schedule.totalAmount * timeElapsedInVestingPeriod) / vestingPeriod;
    }
}

